/*
 * Run-time helpers that GCC 1.42 calls and the gcc 2.95 libgcc.a does not
 * have (gcc 2 expands these operations inline).  Built with gcc 2.95 as
 * libgcc1.a, which is linked after libc.a and before libgcc.a.
 *
 * Same calling convention as GCC 1.42's gnulib/gnulib2.c: arguments on the
 * stack, 64 bit values in d0/d1.  The bodies use plain C operators; gcc 2.95
 * turns them into inline instructions (never into a call of the function
 * itself).  Compile with -fno-builtin.
 *
 * Generated by LLM
 */

typedef int SItype;
typedef unsigned int USItype;
typedef long long DItype;
typedef unsigned long long UDItype;

DItype __adddi3 (DItype a, DItype b) { return a + b; }
DItype __subdi3 (DItype a, DItype b) { return a - b; }
DItype __anddi3 (DItype a, DItype b) { return a & b; }
DItype __iordi3 (DItype a, DItype b) { return a | b; }
DItype __xordi3 (DItype a, DItype b) { return a ^ b; }
DItype __one_cmpldi2 (DItype a) { return ~a; }
DItype __lshldi3 (DItype a, SItype n) { return (UDItype) a << n; }

USItype __umulsi3 (USItype a, USItype b) { return a * b; }
SItype __ashlsi3 (SItype a, SItype n) { return a << n; }
SItype __ashrsi3 (SItype a, SItype n) { return a >> n; }
USItype __lshlsi3 (USItype a, SItype n) { return a << n; }
USItype __lshrsi3 (USItype a, SItype n) { return a >> n; }
